import{_ as e,a as r,o as a,a6 as n}from"./chunks/framework.CJDy2q7X.js";const l=JSON.parse('{"title":"Marketing","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/index.md","filePath":"api/rest-api/admin/marketing/index.md","lastUpdated":1787725411000}'),o={name:"api/rest-api/admin/marketing/index.md"};function s(i,t,d,g,m,u){return a(),r("div",null,t[0]||(t[0]=[n('<h1 id="marketing" tabindex="-1">Marketing <a class="header-anchor" href="#marketing" aria-label="Permalink to &quot;Marketing&quot;">​</a></h1><p>The Marketing section groups everything used to <strong>drive demand, run promotions, talk to customers, and shape how the storefront is found</strong>. It mirrors the admin <strong>Marketing</strong> menu and splits into three sub-menus, each a different lever on sales.</p><h2 id="sub-menus" tabindex="-1">Sub-menus <a class="header-anchor" href="#sub-menus" aria-label="Permalink to &quot;Sub-menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub-menu</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/promotions/">Promotions</a></td><td>Price-and-cart discounting — <strong>Catalog Rules</strong> (automatic price reductions applied to products before they reach the cart), <strong>Cart Rules</strong> (discounts and coupons applied at checkout), and the <strong>Cart Rule Coupons</strong> that back coupon-driven cart rules.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/">Communications</a></td><td>Outbound email — <strong>Email Templates</strong> (reusable HTML bodies), <strong>Events</strong> (dated triggers), <strong>Campaigns</strong> (a template sent to a customer group), and <strong>Newsletter Subscribers</strong> (the audience).</td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/">Search &amp; SEO</a></td><td>How the store is searched and indexed — <strong>Search Terms</strong> (what shoppers typed), <strong>Search Synonyms</strong> (query-widening word groups), <strong>URL Rewrites</strong> (301/302 redirects), and <strong>Sitemaps</strong> (XML sitemaps for crawlers).</td></tr></tbody></table><h2 id="how-the-sub-menus-relate" tabindex="-1">How the sub-menus relate <a class="header-anchor" href="#how-the-sub-menus-relate" aria-label="Permalink to &quot;How the sub-menus relate&quot;">​</a></h2><ul><li><strong>Promotions</strong> decide the <em>price</em> a shopper sees. A <strong>Catalog Rule</strong> rewrites a product&#39;s price store-wide (no coupon, no cart needed); a <strong>Cart Rule</strong> discounts the <em>cart total</em> at checkout, optionally gated by a coupon code drawn from <strong>Cart Rule Coupons</strong>.</li><li><strong>Communications</strong> decide <em>who hears about it</em>. A <strong>Campaign</strong> pairs an <strong>Email Template</strong> with a <strong>customer group</strong> of <strong>Newsletter Subscribers</strong>, optionally anchored to an <strong>Event</strong> date.</li><li><strong>Search &amp; SEO</strong> decide <em>how the store is found</em>. <strong>Search Terms</strong> reveal demand, <strong>Search Synonyms</strong> widen matches, <strong>URL Rewrites</strong> keep old links alive, and <strong>Sitemaps</strong> feed crawlers.</li></ul>',6)]))}const h=e(o,[["render",s]]);export{l as __pageData,h as default};
